/**
 * Computes a content hash for every distinct agdaiDir referenced by any
 * profile in deploy.config.json, and writes scripts/generated-agdai-keys.mjs
 * mapping each raw agdaiDir string to its hash.
 *
 * This key is what static/agdai/<key>/ is actually named (see
 * build-static-assets.mjs) and what src/lib/runtime/interface.ts looks up
 * to build manifestAsset — see scripts/resolve-deploy-config.mjs's
 * getAllAgdaiDirs() for why this is keyed by agdaiDir content, not by
 * library name or agdaLibPath.
 *
 * The generated file is a plain ES module imported by
 * src/lib/runtime/interface.ts at build time (Vite inlines it into the
 * compiled bundle). It's gitignored, like scripts/generated-libraries.mjs.
 *
 * An agdaiDir that doesn't exist yet (not built, or deploy.config.json not
 * configured) is simply absent from the map rather than failing the whole
 * run — same graceful-skip behavior as generate-library-info.mjs, so
 * predev/precheck/prebuild can always produce this file for interface.ts's
 * import to resolve.
 *
 * Usage: node scripts/generate-agdai-keys.mjs
 */

import { writeFile } from 'node:fs/promises'
import { join, relative } from 'node:path'
import { REPO_ROOT, getAllAgdaiDirs } from './resolve-deploy-config.mjs'

const OUT_PATH = join(REPO_ROOT, 'scripts', 'generated-agdai-keys.mjs')

async function main() {
  let entries
  try {
    entries = await getAllAgdaiDirs()
  } catch {
    entries = []
  }

  const keys = {}
  for (const { agdaiDirRaw, agdaiKey } of entries) keys[agdaiDirRaw] = agdaiKey

  const lines = [
    '// Generated by scripts/generate-agdai-keys.mjs — do not edit by hand.',
    '// Re-run `npm run setup` after changing deploy.config.json or rebuilding an agdaiDir.',
    '',
    '/** @type {Record<string, string>} raw agdaiDir string (as written in deploy.config.json) -> content-hash key */',
    `export const GENERATED_AGDAI_KEYS = ${JSON.stringify(keys, null, 2)}`,
    '',
  ]
  await writeFile(OUT_PATH, lines.join('\n'))
  console.log(`Wrote ${Object.keys(keys).length} agdaiDir key${Object.keys(keys).length === 1 ? '' : 's'} to ${relative(REPO_ROOT, OUT_PATH)}`)
}

main().catch(err => { console.error(err); process.exit(1) })
